import{_ as e,o as r,c as o,a2 as i}from"./chunks/framework.Dd_iHz3e.js";const h=JSON.parse('{"title":"Architecture Decision Records (ADR Log)","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/decisions.md","filePath":"system-design/decisions.md"}'),n={name:"system-design/decisions.md"};function d(s,t,a,c,l,g){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="architecture-decision-records-adr-log" tabindex="-1">Architecture Decision Records (ADR Log) <a class="header-anchor" href="#architecture-decision-records-adr-log" aria-label="Permalink to &quot;Architecture Decision Records (ADR Log)&quot;">​</a></h1><p>This log records every foundational technical decision made across the Cooking Nexus codebase, documenting the chosen options, rejected alternatives, deciding factors, trade-offs accepted, and conditions to revisit each choice.</p><hr><h2 id="master-architecture-decision-matrix" tabindex="-1">Master Architecture Decision Matrix <a class="header-anchor" href="#master-architecture-decision-matrix" aria-label="Permalink to &quot;Master Architecture Decision Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Architecture Decision</th><th>Chosen Option</th><th>Alternatives Considered</th><th>Primary Deciding Factors</th><th>Trade-off Accepted</th><th>Revisit When...</th></tr></thead><tbody><tr><td><strong>ADR-01</strong></td><td><strong>Primary Database Engine</strong></td><td><strong>MongoDB + Mongoose</strong></td><td>PostgreSQL, MySQL, DynamoDB, Firebase</td><td>Polymorphic recipe ingredient structures, dynamic JSON schema, fast append-only safety log writes.</td><td>Lacks multi-table strict relational ACID without replica set transactions.</td><td>Creator marketplace requires complex financial royalty ledgers and billing splits.</td></tr><tr><td><strong>ADR-02</strong></td><td><strong>AI Model &amp; Inference Provider</strong></td><td><strong>Google Gemini 3 Flash via Lovable Gateway</strong></td><td>OpenAI GPT-4o, Claude 3.5 Sonnet, Custom Fine-Tuned Model, Groq Llama 3</td><td>Sub-250ms time-to-first-token latency, 1M+ context window, ultra-low token cost ($0.075/1M).</td><td>Reliance on external gateway; potential occasional culinary hallucinations on obscure spices.</td><td>Enterprise private VPC deployment requires on-premises inference or dedicated hosting.</td></tr><tr><td><strong>ADR-03</strong></td><td><strong>AI Streaming Protocol</strong></td><td><strong>Server-Sent Events (SSE)</strong></td><td>WebSockets, Long Polling, Short Polling</td><td>Unidirectional token stream runs over standard HTTP, traverses firewalls, zero stateful connection tax.</td><td>Client cannot send voice feedback upstream over the same open stream.</td><td>Two-way audio conversation mode is introduced for hands-free voice dialog.</td></tr><tr><td><strong>ADR-04</strong></td><td><strong>Authentication Strategy</strong></td><td><strong>Passwordless Magic Links (15m JWT)</strong></td><td>Passwords + bcrypt/Argon2, Auth0, Clerk, Firebase Auth</td><td>Eliminates password management, zero credential leakage risk, removes expensive per-MAU SaaS bills.</td><td>Users must check email to authenticate, adding a short onboarding delay.</td><td>Corporate Single Sign-On (SSO) or OAuth2 (Google/Apple) is required by consumer research.</td></tr><tr><td><strong>ADR-05</strong></td><td><strong>Frontend Application Framework</strong></td><td><strong>React 18 + Vite (SPA)</strong></td><td>Next.js 14 App Router, Vue 3, Svelte 5, Angular 18</td><td>Rich component ecosystem (Radix UI, Lucide), fast HMR in Vite, optimal for client-side audio timers.</td><td>Initial JavaScript bundle download required before page becomes interactive.</td><td>Public recipe pages require server-side rendering (SSR) for search engine crawler indexing.</td></tr><tr><td><strong>ADR-06</strong></td><td><strong>UI Design System &amp; Styling</strong></td><td><strong>Tailwind CSS + Headless Radix UI</strong></td><td>Material UI (MUI), Chakra UI, Styled Components</td><td>Zero runtime CSS overhead, accessible WAI-ARIA compliance out of the box, total visual customization.</td><td>Utility class density in JSX code; requires disciplined component composition.</td><td>Design team transitions to an enterprise design token system like Figma Tokens Studio.</td></tr><tr><td><strong>ADR-07</strong></td><td><strong>Kitchen Hazard Ingestion Pattern</strong></td><td><strong>Edge Optical Classification + JSON Telemetry</strong></td><td>Cloud Video Streaming, Raw RTSP Stream Ingest</td><td>99% bandwidth reduction, protects private home kitchen video privacy, sub-50ms hazard response.</td><td>Cannot review historical video clips of cooking fires in the cloud.</td><td>Commercial restaurant insurance policies demand verified cloud video incident archives.</td></tr><tr><td><strong>ADR-08</strong></td><td><strong>Kitchen Multi-Timer Engine</strong></td><td><strong>HTML5 Web Audio API + Epoch Time</strong></td><td>Server-side WebSocket timer, standard setInterval</td><td>Operates completely offline without network latency, immune to browser background tab throttling.</td><td>Timers reset if browser window or application cache is forcibly closed.</td><td>Cross-device timer synchronization is added to display countdowns on smart watches.</td></tr><tr><td><strong>ADR-09</strong></td><td><strong>Client Server-State Management</strong></td><td><strong>TanStack React Query v5</strong></td><td>Redux Toolkit, Zustand, MobX, React Context</td><td>Automated background refetching, request de-duplication, built-in stale-while-revalidate caching.</td><td>Additional runtime dependency weight (~12kB gzip).</td><td>Application state becomes predominantly local and synchronous.</td></tr><tr><td><strong>ADR-10</strong></td><td><strong>Video Reel Playback Architecture</strong></td><td><strong>HTML5 Video Element + CSS Snap Scroll</strong></td><td>Video.js, Plyr, Third-Party Iframe Embeds</td><td>Full control over gesture listeners, zero licensing fees, lightweight mobile GPU memory footprint.</td><td>Must manually handle HLS/DASH media source extensions and buffering indicators.</td><td>Adaptive bitrate streaming (HLS) with DRM protection is required for premium creator masterclasses.</td></tr></tbody></table>',5)])])}const u=e(n,[["render",d]]);export{h as __pageData,u as default};
